"""Build a compact rule report with a synchronized pressure/counter replay."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'training/results/burst-study'


def main():
    study=json.loads((OUT/'rules-tactics.json').read_text())
    confirmation=json.loads((OUT/'rules-confirmation.json').read_text())
    pairs=confirmation['configs']['burst96-cost8-half']
    actual=study['actual_tactic']
    branch=next(b for b in actual['counter_branches'] if b['start']['tick']==727 and b['target_center']==19)
    baseline=study['pairs']['attack:safe']['replays'][0]
    prefix=[f for f in baseline['frames'] if f['tick']<=727]
    counter=prefix+branch['frames']
    data=json.dumps(dict(start=650,baseline=baseline['frames'],counter=counter,
        baselineEnd=baseline['ticks'],counterEnd=branch['end_tick']),separators=(',',':'))
    rows=''.join(f'<tr><td>{name}</td><td>{r["summary"]["wins"]} / {r["summary"]["losses"]} / {r["summary"]["draws"]}</td><td>{r["summary"]["median_decisive_returns"] or "—"}</td><td>{r["summary"]["mean_ticks"]/30:.1f}s</td></tr>' for name,r in pairs.items())
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rally Lab · Burst preview rules</title><link rel="icon" href="/mark.svg">
<style>*{box-sizing:border-box}body{margin:0;background:#f5f6f0;color:#203c30;font:15px/1.65 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:32px 22px 60px}nav{display:flex;justify-content:space-between;gap:14px;margin-bottom:38px}a{color:#326b43}h1{font-size:clamp(34px,6vw,62px);line-height:1.07;letter-spacing:-.045em;max-width:850px}h2{font-size:25px;line-height:1.2}p{max-width:920px;color:#576b5d}section{background:#fdfff9;border:1px solid #dce3d6;border-radius:12px;padding:24px;margin-top:22px;min-width:0}.tag{font:11px monospace;letter-spacing:.1em;color:#6c875c}.note{font-size:12px;color:#61745e}.court-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.court-title{font-size:15px;font-weight:650;margin-bottom:8px}.court{display:block;background:#17382d;width:100%;aspect-ratio:2.25;overflow:visible}.readout{font:12px monospace;display:flex;justify-content:space-between;gap:8px;margin-top:7px;flex-wrap:wrap}.energy{display:flex;align-items:center;gap:7px;font-size:12px;margin-top:8px}.energy span{width:70px}.energy progress{height:10px;flex:1;accent-color:#c77a3d}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}button,select{min-height:42px;border:1px solid #bdcdb9;background:#f0f5e9;color:#203c30;border-radius:6px;padding:8px 13px;font:inherit;cursor:pointer}button:hover{background:#e4eddc}input[type=range]{width:100%;min-height:36px;accent-color:#386f4d}.table-wrap{overflow-x:auto}table{border-collapse:collapse;min-width:560px;width:100%;font-size:13px}th,td{text-align:left;padding:11px;border-bottom:1px solid #e0e6d9}th{color:#61745e;font-weight:500}code{background:#ebf0e3;padding:2px 5px;border-radius:4px;overflow-wrap:anywhere}pre{white-space:pre-wrap;font-size:12px;background:#edf2e7;padding:14px;border-radius:6px}li{margin:8px 0}.callout{border-left:4px solid #789661;padding-left:16px}.badge{display:inline-block;background:#e7eedf;padding:5px 10px;border-radius:20px;font-size:12px}@media(max-width:650px){main{padding:24px 14px 40px}section{padding:17px}.court-grid{grid-template-columns:1fr}nav{margin-bottom:26px}h2{font-size:22px}}</style>
<main><nav><a href="/">← Arena</a><a href="pong-burst-v1.zip">Standalone training package ↓</a></nav><div class="tag">RALLY LAB / PONG-BURST-V1</div><h1>Make movement<br>a decision.</h1><span class="badge">Playable preview · separate rules and rankings</span><p>Ordinary movement stays available. A short burst gives the paddle extra reach, then its visible energy meter must recover. The ball accelerates half as quickly as Classic v4. This preview tests whether placement and resource use can create longer, understandable exchanges.</p>
<section><h2>Pressure, then a counter</h2><p>The attacking script repeatedly sends the ball to the top. The defender reaches it but spends energy each cycle. Once its meter is nearly empty, the attacker switches to the bottom and scores. The second replay changes one return: the defender spends <em>more</em> energy to contact at Y=19 instead of Y=18. That changes the shot angle and breaks the pattern; the same controllers then reach a loop draw.</p><p class="note">Actual diagnostic replay: seed 2,828,560,875, rally 1. Both panes share the recorded prefix. The alternative uses an exactly reachable 26-action path, then resumes the original policies. These are geometric diagnostic controllers, not trained weights.</p>
<div class="court-grid"><div><div class="court-title">Recorded defender · loses the point</div><svg class="court" id="court-a" viewBox="0 0 360 160" role="img" aria-label="Recorded attack and defense"><path d="M180 4V156" stroke="#688779" stroke-dasharray="3 4"/><rect x="12" width="4" height="24" fill="#87e8b8" data-left/><rect x="344" width="4" height="24" fill="#f6ac70" data-right/><circle r="3" fill="#f3ffd6" data-ball/></svg><div class="readout"><span data-a-returns></span><span data-a-state></span></div><div class="energy"><span>Defender</span><progress max="96" value="96" data-a-energy></progress><b data-a-meter></b></div></div>
<div><div class="court-title">Alternative return · reaches a draw</div><svg class="court" id="court-b" viewBox="0 0 360 160" role="img" aria-label="Alternative placement counter"><path d="M180 4V156" stroke="#688779" stroke-dasharray="3 4"/><rect x="12" width="4" height="24" fill="#87e8b8" data-left/><rect x="344" width="4" height="24" fill="#f6ac70" data-right/><circle r="3" fill="#f3ffd6" data-ball/></svg><div class="readout"><span data-b-returns></span><span data-b-state></span></div><div class="energy"><span>Defender</span><progress max="96" value="96" data-b-energy></progress><b data-b-meter></b></div></div></div>
<div class="controls"><button id="play">Play</button><button data-seek="701">Pressure</button><button data-seek="727">Alternative return</button><button data-seek="883">Final attack</button><label>Speed <select id="speed"><option value="1">1×</option><option value="2" selected>2×</option><option value="4">4×</option></select></label><span id="tick" class="tag"></span></div><label class="note" for="timeline">Recorded simulation tick</label><input id="timeline" type="range" min="650" step="1"><p class="note">Mint: attacker. Orange: defender. Tick 883 starts the last shot in the losing branch. From that exact position, exhaustive action reachability finds no return with its recorded energy of 3; restoring its energy to 96 makes a return possible.</p>
<p class="callout">This demonstrates a local resource consequence and a legal placement counter. It does not prove the attacker can force this sequence against every defense, or that any trained network has learned it.</p></section>
<section><h2>What the fresh rule tests show</h2><p>Each pairing uses 32 fresh seeds, all five serves and both sides: 320 rallies. The stronger defender considers every legal opposing reply angle and plans energy-aware recovery. It is still a finite-horizon heuristic.</p><div class="table-wrap"><table><thead><tr><th>Pairing</th><th>Wins / losses / draws</th><th>Median scored returns</th><th>Mean rally time</th></tr></thead><tbody>__ROWS__</tbody></table></div><p>Attacking mirrors sustain 19 returns at the median, compared with 11 in the earlier v4 study. This is a contextual comparison across separate studies, not a matched-seed causal estimate. The stronger defender can still draw many attacking rallies; two such defenders draw throughout this test. No strong-script point ended before the second return.</p></section>
<section><h2>A small, explicit rule addition</h2><ul><li>Normal up/down: 2 units per tick. Burst up/down: 4 units if at least 8 energy is available.</li><li>Each paddle starts with 96 energy. A successful burst costs 8; every normal action restores 1, including normal movement. An exhausted burst request moves normally but does not recharge.</li><li>Every return increases horizontal speed by 0.5, from 5 to a cap of 13. Placement sets the angle. The cap arrives after 16 returns, around 21 seconds into an uninterrupted rally.</li><li>Models see eight inputs: the original six plus both energy meters. Five outputs choose up, stay, down, burst up or burst down. Energy belongs in the exact loop-state key.</li></ul><p>The 96/8 budget was retained for the preview because it gives a 12-tick full burst and longer pressured exchanges than the shorter tested budgets. No physical-phone or subjective human-playtest result is claimed.</p></section>
<section><h2>Reproduce and train independently</h2><p>The downloadable package contains standalone TypeScript and Python engines, a headless example, and exact action fixtures. Checks cover 12,000 independent scalar/vector transitions, 102 isolated examples and three full matches; TypeScript and Python agree on 11,905 full-match frames. Models trained for Classic v4 are not compatible with this eight-input/five-output contract.</p><pre>python3 training/burst/check.py
node --import tsx training/burst/check.ts
.venv/bin/python training/scripts/burst_check.py
.venv/bin/python training/scripts/burst_tactics.py
python3 training/scripts/burst_tactic_check.py
.venv/bin/python training/scripts/burst_study.py --confirmation --count 32 --out /tmp/new-burst-confirmation.json
python3 training/scripts/package_burst.py
python3 training/scripts/burst_report.py</pre><p class="note">Raw evidence and exact branches: <code>training/results/burst-study/rules-*.json</code>. Confirmation seeds are now consumed; future tuning needs new reserved seeds. Current model-size experiments are separate from these scripted rule demonstrations.</p></section><p class="note">Rally Lab · Burst preview · <a href="/">Play or watch →</a></p></main>
<script>
const data=__DATA__;
const range=document.getElementById('timeline'), play=document.getElementById('play'), speed=document.getElementById('speed');
let at=data.start, playing=false, last=0, debt=0;
const end=Math.max(data.baselineEnd,data.counterEnd);range.max=end;range.value=at;
function frameAt(frames,t){return frames[Math.min(frames.length-1,Math.max(0,t-frames[0].tick))];}
function pane(id,key,frames,t,endTick){const f=frameAt(frames,t),svg=document.getElementById(id);svg.querySelector('[data-left]').setAttribute('y',f.paddles[0]-12);svg.querySelector('[data-right]').setAttribute('y',f.paddles[1]-12);const ball=svg.querySelector('[data-ball]');ball.setAttribute('cx',f.ball[0]);ball.setAttribute('cy',f.ball[1]);document.querySelector('[data-'+key+'-returns]').textContent=f.returns+' returns';document.querySelector('[data-'+key+'-state]').textContent=t>=endTick?(key==='a'?'Attacker scores':'Loop draw'):'In play';document.querySelector('[data-'+key+'-energy]').value=f.energy[1];document.querySelector('[data-'+key+'-meter]').textContent=f.energy[1]+'/96';}
function draw(){range.value=at;document.getElementById('tick').textContent='TICK '+at;pane('court-a','a',data.baseline,at,data.baselineEnd);pane('court-b','b',data.counter,at,data.counterEnd);}
function pause(){playing=false;play.textContent='Play';}
range.addEventListener('input',()=>{pause();at=Number(range.value);draw();});
document.querySelectorAll('[data-seek]').forEach(b=>b.addEventListener('click',()=>{pause();at=Number(b.dataset.seek);draw();}));
play.addEventListener('click',()=>{if(playing){pause();return;}if(at>=end)at=data.start;playing=true;play.textContent='Pause';last=performance.now();debt=0;requestAnimationFrame(tick);});
function tick(now){if(!playing)return;debt+=Math.min(100,now-last)*Number(speed.value);last=now;while(debt>=1000/30&&at<end){at++;debt-=1000/30;}draw();if(at>=end)pause();else requestAnimationFrame(tick);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});draw();
</script></html>'''
    html=template.replace('__ROWS__',rows).replace('__DATA__',data)
    path=ROOT/'public/training/burst-rules.html'
    path.write_text(html)
    print(path)


if __name__=='__main__':main()
